T.moon.position.set(mx, 0, mz);
T.earth.rotation.y = t;
// camera rides behind Earth, looking at the Moon
const ang = Math.atan2(mz, mx);
T.camera.position.set(-Math.cos(ang) * 1.6, 0.5, -Math.sin(ang) * 1.6);
T.camera.lookAt(mx, 0, mz);
T.draw();
const ph = Math.cos(a - Math.PI);
const name = ph > 0.7 ? 'Full' : ph > 0.2 ? 'Gibbous' : ph > -0.2 ? 'Half' : ph > -0.7 ? 'Crescent' : 'New';
api.label(name, api.w / 2, 140, {k: api.seg(t, 0.3, 1)});
api.say('From Earth we see phases', 0.4, 6.5);

